using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace PeerChatDesktop {
public partial class DesktopApplication {
    readonly IConnectionPreviewProvider connectionPreviewProvider=new SampleConnectionPreviewProvider();
    ConnectionPreviewState connectionPreviewState=ConnectionPreviewState.Connected;ConnectionPreviewSnapshot connectionPreview;
    ComboBox connectionPreviewExamples;string previewSessionId="",previewFailureId="",previewSeverity="All",previewType="All",previewEventSession="All",previewLogSearch="";bool previewStructured;
    TextBlock PreviewText(string text){return new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,Foreground=Brush("#B7C9D9"),FontSize=diagnosticTextSize,Margin=new Thickness(8)};}
    ComboBox PreviewSelector(string name,string[] values,string selected){var selector=new ComboBox{Name=name,MinWidth=160,Margin=new Thickness(0,0,10,8)};foreach(var value in values)selector.Items.Add(new ComboBoxItem{Tag=value,Content=new TextBlock{Text=value,Foreground=Brush("#EDF1F5")}});selector.SelectedIndex=Math.Max(0,Array.IndexOf(values,selected));System.Windows.Automation.AutomationProperties.SetName(selector,name);return selector;}
    static string PreviewSelection(ComboBox selector){var item=selector.SelectedItem as ComboBoxItem;return item==null?"All":Convert.ToString(item.Tag);}
    void BuildConnectionPreviewSelector(WrapPanel row){
        connectionPreviewExamples=PreviewSelector("ConnectionSampleState",Enum.GetValues(typeof(ConnectionPreviewState)).Cast<ConnectionPreviewState>().Select(SampleConnectionPreviewProvider.Label).ToArray(),SampleConnectionPreviewProvider.Label(connectionPreviewState));connectionPreviewExamples.Visibility=Visibility.Collapsed;row.Children.Add(connectionPreviewExamples);
        connectionPreviewExamples.SelectionChanged+=(s,e)=>{connectionPreviewState=(ConnectionPreviewState)connectionPreviewExamples.SelectedIndex;if(diagnosticContext.Section==DiagnosticSection.Connections)RenderConnectionPreview();};
    }
    Border PreviewCard(string title,UIElement content){var body=new StackPanel();body.Children.Add(new TextBlock{Text=title,Foreground=Brush("#83CCFC"),FontSize=15,FontWeight=FontWeights.SemiBold,Margin=new Thickness(12)});body.Children.Add(content);return new Border{Child=body,Background=Brush("#111F2B"),BorderBrush=Brush("#2B4355"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(9),Margin=new Thickness(0,0,0,12)};}
    Border PreviewMetricCard(DiagnosticPanel panel){var body=new StackPanel{Margin=new Thickness(4,0,4,8)};foreach(var metric in panel.Metrics){var grid=new Grid{Margin=new Thickness(8,diagnosticCompact?2:5,8,diagnosticCompact?2:5)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});grid.Children.Add(new TextBlock{Text=metric.Label,TextWrapping=TextWrapping.Wrap,Foreground=Brush("#A8B9C8"),FontSize=diagnosticTextSize});var value=new TextBlock{Text=metric.Value,TextWrapping=TextWrapping.Wrap,Foreground=Brush("#EDF1F5"),FontSize=diagnosticTextSize};Grid.SetColumn(value,1);grid.Children.Add(value);body.Children.Add(grid);}return PreviewCard(panel.Title,body);}
    ListBox PreviewList(string name){var list=new ListBox{Name=name,MaxHeight=210,MinHeight=90,Margin=new Thickness(8),Background=Brush("#14222E"),Foreground=Brush("#EDF1F5"),BorderThickness=new Thickness(0),HorizontalContentAlignment=HorizontalAlignment.Stretch};list.ItemTemplate=(DataTemplate)System.Windows.Markup.XamlReader.Parse("<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><TextBlock Text='{Binding Summary}' TextWrapping='Wrap' Margin='8' Foreground='#EDF1F5'/></DataTemplate>");ScrollViewer.SetHorizontalScrollBarVisibility(list,ScrollBarVisibility.Disabled);return list;}
    StackPanel PreviewBody(){return new StackPanel{Margin=new Thickness(8)};}
    void PreviewPage(string tab,StackPanel body){((TabItem)groupDiagnosticTabs.Items.Cast<TabItem>().Single(t=>Convert.ToString(t.Header)==tab)).Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};}
    void RenderConnectionPreview(){
        if(groupDiagnosticTabs==null||diagnosticContext.Section!=DiagnosticSection.Connections)return;connectionPreview=connectionPreviewProvider.Read(connectionPreviewState);diagnosticBanner.Text=ConnectionPreviewSnapshot.SampleBanner;
        var overview=PreviewBody();foreach(var panel in connectionPreview.Overview)overview.Children.Add(PreviewMetricCard(panel));PreviewPage("Overview",overview);
        var network=PreviewBody();foreach(var panel in connectionPreview.Network)network.Children.Add(PreviewMetricCard(panel));network.Children.Add(PreviewCard("Network graphs",PreviewText("N/A — RTT, bandwidth and retransmission measurements are not connected. No media route is inferred from the control connection.")));PreviewPage("Network",network);
        RenderPreviewSessions();RenderPreviewFailures();RenderPreviewEvents();RenderPreviewLogs();
    }
    string PreviewEmpty(string noun){return connectionPreviewState==ConnectionPreviewState.Loading?"Loading "+noun+" (preview only; no collector is running)…":connectionPreviewState==ConnectionPreviewState.Unavailable?noun+" unavailable · N/A — no instrumentation connected":"No "+noun+" in this sample state.";}
    void RenderPreviewSessions(){
        var body=PreviewBody();body.Children.Add(PreviewText("SAMPLE sessions · established sessions, attempts and reconnects have distinct labels and stable sample identifiers."));var list=PreviewList("ConnectionSessions");list.ItemsSource=connectionPreview.Sessions;body.Children.Add(PreviewCard("Select a sample session",list));var detail=new StackPanel();body.Children.Add(PreviewCard("Selected session details",detail));
        Action update=()=>{detail.Children.Clear();var selected=list.SelectedItem as ConnectionPreviewSession;previewSessionId=selected==null?"":selected.Id;if(selected==null){detail.Children.Add(PreviewText(PreviewEmpty("sessions")));return;}detail.Children.Add(PreviewText("SAMPLE · "+selected.Label+"\nContact / group: "+selected.Target+"\nType: "+selected.Kind+"\nSession ID: "+selected.Id+"\nStart: "+selected.StartedUtc.ToString("yyyy-MM-dd HH:mm:ss")+" UTC\nDuration: "+(selected.Duration.HasValue?selected.Duration.Value.ToString():"N/A")+"\nOutcome: "+selected.Outcome+"\nRoute: "+selected.Route+"\nAttempt correlation: "+selected.CorrelationId));};list.SelectionChanged+=(s,e)=>update();list.SelectedItem=connectionPreview.Sessions.FirstOrDefault(s=>s.Id==previewSessionId)??connectionPreview.Sessions.FirstOrDefault();update();PreviewPage("Sessions",body);
    }
    void RenderPreviewFailures(){
        var body=PreviewBody();body.Children.Add(PreviewText("SAMPLE failures · selecting or expanding a failure never reconnects or changes a real session."));var list=PreviewList("ConnectionFailures");list.ItemsSource=connectionPreview.Failures;body.Children.Add(PreviewCard("Recent sample failures",list));var detail=new Expander{Name="ConnectionFailureDetails",Header="Expand selected failure details",IsExpanded=true,Foreground=Brush("#83CCFC"),Margin=new Thickness(8)};body.Children.Add(PreviewCard("Failure and recovery",detail));
        Action update=()=>{var selected=list.SelectedItem as ConnectionPreviewFailure;previewFailureId=selected==null?"":selected.Id;detail.Content=PreviewText(selected==null?PreviewEmpty("failures"):"SAMPLE failure: "+selected.Id+"\nReason: "+selected.Reason+"\nStage: "+selected.Stage+"\nAssociated contact / group: "+selected.Target+"\nTime: "+selected.TimestampUtc.ToString("yyyy-MM-dd HH:mm:ss")+" UTC\nSession / attempt: "+selected.SessionId+"\nRecovery: "+selected.Recovery);};list.SelectionChanged+=(s,e)=>update();list.SelectedItem=connectionPreview.Failures.FirstOrDefault(f=>f.Id==previewFailureId)??connectionPreview.Failures.FirstOrDefault();update();PreviewPage("Failures",body);
    }
    void RenderPreviewEvents(){
        var body=PreviewBody();body.Children.Add(PreviewText("SAMPLE chronological timeline · correlation IDs connect repeated attempts. Filters affect this preview only."));var filters=new WrapPanel();
        var severity=PreviewSelector("EventSeverity",new[]{"All","Info","Warning","Error"},previewSeverity);var type=PreviewSelector("EventType",new[]{"All"}.Concat(Enum.GetNames(typeof(ConnectionPreviewEventType))).ToArray(),previewType);var session=PreviewSelector("EventSession",new[]{"All"}.Concat(connectionPreview.Sessions.Select(s=>s.Id)).ToArray(),previewEventSession);
        foreach(var pair in new[]{Tuple.Create("Severity",severity),Tuple.Create("Event type",type),Tuple.Create("Session",session)}){var field=new StackPanel();field.Children.Add(PreviewText(pair.Item1));field.Children.Add(pair.Item2);filters.Children.Add(field);}body.Children.Add(filters);var list=PreviewList("ConnectionEvents");list.MaxHeight=420;body.Children.Add(PreviewCard("Event timeline (sample)",list));var empty=PreviewText("");body.Children.Add(empty);
        Action update=()=>{previewSeverity=PreviewSelection(severity);previewType=PreviewSelection(type);previewEventSession=PreviewSelection(session);var rows=ConnectionPreviewQuery.Filter(connectionPreview,previewSeverity,previewType,previewEventSession);list.ItemsSource=rows;empty.Text=rows.Length==0?(connectionPreview.Events.Length==0?PreviewEmpty("events"):"No sample events match these filters."):rows.Length+" sample events · UTC order";};severity.SelectionChanged+=(s,e)=>update();type.SelectionChanged+=(s,e)=>update();session.SelectionChanged+=(s,e)=>update();update();PreviewPage("Events",body);
    }
    void RenderPreviewLogs(){
        var body=PreviewBody();body.Children.Add(PreviewText("SAMPLE LOGS ONLY · sensitive values appear as [REDACTED]. This preview does not read original Connection & Diagnostics, application logs or crash reports."));
        var controls=new WrapPanel();var search=new TextBox{Name="ConnectionLogSearch",Text=previewLogSearch,MinWidth=220,Margin=new Thickness(0,0,10,8),ToolTip="Search sample log lines",Background=Brush("#14222E"),Foreground=Brush("#EDF1F5")};var mode=PreviewSelector("ConnectionLogPresentation",new[]{"Readable","Structured"},previewStructured?"Structured":"Readable");controls.Children.Add(search);controls.Children.Add(mode);body.Children.Add(PreviewText("Search sample logs"));body.Children.Add(controls);
        var logs=new TextBox{Name="ConnectionRawLogs",IsReadOnly=true,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=180,MaxHeight=380,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,FontFamily=new FontFamily("Consolas"),FontSize=diagnosticTextSize,Background=Brush("#111D27"),Foreground=Brush("#EDF1F5"),Padding=new Thickness(12)};body.Children.Add(PreviewCard("Redacted sample diagnostic text",logs));
        Action update=()=>{previewLogSearch=search.Text;previewStructured=PreviewSelection(mode)=="Structured";logs.Text=ConnectionPreviewQuery.Logs(connectionPreview,previewLogSearch,previewStructured);};search.TextChanged+=(s,e)=>update();mode.SelectionChanged+=(s,e)=>update();update();
        var actions=new WrapPanel();Action<string,Action> add=(title,callback)=>{var button=new Button{Content=title,Padding=new Thickness(12,7,12,7),Margin=new Thickness(0,8,8,0)};button.Click+=(s,e)=>callback();actions.Children.Add(button);};add("Copy sample logs",()=>CopyDiagnosticText(logs.Text,"Sample connection logs copied (not a real report)."));add("Export sample logs…",()=>{var pick=new Microsoft.Win32.SaveFileDialog{FileName="PeerChat-SAMPLE-connections.txt",Filter="Text|*.txt"};if(pick.ShowDialog(groupDiagnosticWindow)==true)try{System.IO.File.WriteAllText(pick.FileName,logs.Text,new System.Text.UTF8Encoding(false));}catch{Notify("Could not export sample logs.");}});body.Children.Add(actions);PreviewPage("Raw Logs",body);
    }
}
}
